DO $background_removal_sync$
DECLARE
  payload jsonb := $background_removal_sync_3af685ac98b8d431${"bundle":"loomic-design-skills-v2","package":{"manifest":{"slug":"background-removal","name":"背景去除与透明素材","description":"将已有图片编辑为透明背景 PNG，或生成透明素材；区分图片透明处理与画板透明导出。","version":"2.2.0","category":"design","iconName":"scissors","license":null,"metadata":{"bundle":"loomic-design-skills-v2","loomic":{"schemaVersion":1,"execution":"image","intents":["background-removal","cutout","transparent-background"],"outputKinds":["transparent-png"],"requiredTools":["edit_image"],"optionalTools":["generate_image","inspect_design","get_design_objects","update_design_brief","verify_design_result","get_brand_kit"],"models":[{"role":"image","required":true,"preferredIds":[]}],"limitations":["技能不增加运行时工具、模型、权限或预算；用户局部修改不扩展为重设计。","本包为 Loomic 原创流程，研究来源不是效果 benchmark；未运行上游脚本或自动下载依赖。","已有图片使用 edit_image.operation=generate、sourceUsage=edit、sourceAssetIds、background=transparent 与 outputFormat=png；新透明素材使用 generate_image，并明确同样的透明背景与 PNG 输出。","图片编辑可能改变主体细节，不保证产品标签、文字、纹理逐像素保真；透明输出检查不等于视觉质量验收。","透明背景不是局部主体选择或交互蒙版；不能用提示词声称实现了未提供的精细抠图能力。"],"examples":["只去掉这张产品照片的背景，产品和标签不能变。"],"sources":[{"title":"OpenAI Image generation：透明背景与图像编辑","url":"https://developers.openai.com/api/docs/guides/image-generation","relation":"inspired-by"}],"composition":{"role":"domain","stages":["design"]}}}},"content":"---\nname: background-removal\ndescription: 将已有图片编辑为透明背景 PNG，或生成透明素材；区分图片透明处理与画板透明导出。\nmetadata:\n  author: loomic\n  version: \"2.2.0\"\n---\n\n# 背景去除与透明素材\n\n先区分三种请求：已有图片主体分离、新生成素材要透明、画板导出透明。保留当前目标和原始资产，明确要保留的主体；头发、玻璃、白色产品和孔洞需要实际预览才能判定效果。\n\n已有图片使用 edit_image：operation=generate、sourceUsage=edit、sourceAssetIds=[原图]、background=transparent、outputFormat=png。它直接提交当前已解析的原图编辑任务，保留原始资产；不能把方案或请求已提交说成透明素材已生成。新生成素材则使用 generate_image，并同样明确 background=transparent 与 outputFormat=png。缺少适用工具、已启用的图片模型或源图时如实说明，不虚构旧确认步骤，不下载模型。\n\n透明参数请求的是生成结果的透明背景，不能借助提示词只选择某个主体或指定交互蒙版；outputFormat=png 本身也不替代 background=transparent。图片编辑可能改变主体文字、纹理与边缘，不是逐像素分割。用户明确要求产品标签或原图像素完全不变时，先说明此能力限制，不把该流程描述为无损方案。画板透明导出只影响导出底色，不去掉照片像素内背景。按任务需要读 [透明处理边界](references/workflow.md)。\n\n## Loomic 范围\n\n只建议/分析时不调用写入或生成。后续若用户要求落地，使用当前真实目标、工具与模型；update_design_brief 可用时合并仍有效的保留项和最新纠正。已禁用技能、用户权限、目标锁和付费确认不能由本说明绕过。未收到实际图像不声称视觉验收；不存在的工具不能靠提示词补齐。\n","files":[{"file_path":"references/workflow.md","content":"# 背景去除与透明素材：按需细则\n\n## 原图抠图\n确认是哪个 image/canvas_image 与源 assetId，不能把预览缩略图或上次生成结果当源图。已有图片调用 edit_image 时明确 operation=generate、sourceUsage=edit、sourceAssetIds=[原图]、background=transparent、outputFormat=png。它直接提交已绑定源图的编辑任务；不存在源图、适用图片模型或 edit_image 工具时停止。新透明素材才使用 generate_image，并明确 background=transparent 与 outputFormat=png。\n\n独立画布图片通常在原图旁生成新图片，保留原始资产；如果本轮绑定了原生设计目标，先读取目标、版本与源图对象，使用该设计的真实 target，不能意外写入其他画板或替换背景层。只有用户明确要求替换原对象时才带真实的替换对象 ID。提交前复述保留主体与编辑风险；工具完成前不能声称已生成。失败不得自行换模型或重启付费任务；异步 processing 也不等于失败。\n\n## 原生背景与导出\ncanvas.background=null 或透明 PNG 只处理画布底色；全幅背景图层和照片内背景仍会存在。删除背景层是设计对象变更，应遵守目标范围与确认，不能把 opacity=0/几何 mask 当作主体分割。\n\n## 质量与费用\n透明边缘、半透明主体、阴影保留需看真实结果。API 不是逐像素抠图，产品标签、文字和纹理可能被重绘；严格原样保真应明确告知限制，不能把调用成功等同于视觉验收。服务端的 alpha 校验只证明有透明像素，不证明边缘质量。处理错误不能擅自付费重画或增加其他模型；保留原图并说明未达标位置。没有实际预览证据就不能声称“已抠干净”。\n\n## 能力来源与维护\n\n本说明为 Loomic 原生流程，公开资料只启发设计方法，不声称上游脚本或所有模型已在 Loomic 验证。工具协议以当前运行时 schema 为准；此包不运行 shell、不下载模型。来源、适用意图、模型角色与限制见包 manifest 元数据。\n","mime_type":"text/markdown"}]}}$background_removal_sync_3af685ac98b8d431$::jsonb;
  entry jsonb;
  expected_bundle text;
  target_id uuid;
  file_entry jsonb;
BEGIN
  entry := payload->'package';
  expected_bundle := payload->>'bundle';
  IF expected_bundle IS NULL OR entry->'manifest'->>'slug' IS DISTINCT FROM 'background-removal'
    OR entry->'manifest'->'metadata'->>'bundle' IS DISTINCT FROM expected_bundle THEN
    RAISE EXCEPTION 'Background-removal sync payload has an unexpected bundle or slug';
  END IF;

  -- Do not insert: a missing row means the prerequisite catalog migration was not applied.
  SELECT s.id INTO target_id FROM public.skills AS s
    WHERE s.slug = 'background-removal' FOR UPDATE;
  IF target_id IS NULL THEN
    RAISE EXCEPTION 'Background-removal system skill is missing; apply the catalog seed before this sync';
  END IF;
  IF EXISTS (SELECT 1 FROM public.skills AS s WHERE s.id = target_id
      AND (s.source IS DISTINCT FROM 'system' OR s.created_by IS NOT NULL
        OR s.metadata->>'bundle' IS DISTINCT FROM expected_bundle)) THEN
    RAISE EXCEPTION 'Background-removal skill is not the expected system package; nothing was changed';
  END IF;

  UPDATE public.skills AS owned SET
    name = entry->'manifest'->>'name', description = entry->'manifest'->>'description', author = 'Loomic',
    version = entry->'manifest'->>'version', license = entry->'manifest'->>'license',
    category = entry->'manifest'->>'category', icon_name = entry->'manifest'->>'iconName',
    skill_content = entry->>'content', metadata = COALESCE(owned.metadata, '{}'::jsonb) || entry->'manifest'->'metadata',
    updated_at = now()
  WHERE owned.id = target_id AND owned.source = 'system' AND owned.created_by IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'Background-removal ownership changed concurrently; nothing was changed'; END IF;

  FOR file_entry IN SELECT value FROM jsonb_array_elements(entry->'files') LOOP
    INSERT INTO public.skill_files (skill_id, file_path, content, mime_type)
    VALUES (target_id, file_entry->>'file_path', file_entry->>'content', file_entry->>'mime_type')
    ON CONFLICT (skill_id, file_path) DO UPDATE SET
      content = EXCLUDED.content, mime_type = EXCLUDED.mime_type, updated_at = now();
  END LOOP;
  -- Keep this package exact when a future source revision removes a reference.
  DELETE FROM public.skill_files AS f WHERE f.skill_id = target_id AND f.file_path LIKE 'references/%'
    AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(entry->'files') AS item
      WHERE item->>'file_path' = f.file_path);
END;
$background_removal_sync$;
